with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('donere', 'word', '23ec012e-379b-5f55-a903-4f9b469a9ac9', 1, 'verb', null, 'to donate', 'Han donerede penge til velgørenhed.', 'He donated money to charity.'), ('kommunalreform', 'word', '43f9b44e-d30e-5bde-8f8f-617f9546f7ca', 1, 'noun', 'en', 'municipal reform', 'Kommunalreformen ændrede grænserne mellem kommuner.', 'The municipal reform changed the boundaries between municipalities.'), ('kommunisme', 'word', 'a7edde61-23fd-51e5-9291-d782cc68245b', 1, 'noun', 'en', 'communism', 'Bogen handler om kommunismens historie.', 'The book is about the history of communism.'), ('tackle', 'word', '13365860-8b55-535b-8596-c5ff3ac38fa7', 1, 'verb', null, 'to handle, to cope with', 'Hun ved, hvordan man tackler stress.', 'She knows how to handle stress.'), ('henrette', 'word', 'a717288f-33c7-5fb3-a7f3-50c421a15c69', 1, 'verb', null, 'to execute', 'Fangen blev henrettet ved daggry.', 'The prisoner was executed at dawn.'), ('ihærdig', 'word', '17476726-b8df-5837-b738-0d83fdbaeb7d', 1, 'adjective', null, 'diligent, persistent', 'Hun gjorde en ihærdig indsats for at lære sproget.', 'She made a persistent effort to learn the language.'), ('missil', 'word', 'e2f0b9b5-210f-56ed-a267-1d6cc5c1abe9', 1, 'noun', 'et', 'missile', 'Landet testede et nyt missil.', 'The country tested a new missile.'), ('velhavende', 'word', '1170dc39-b186-5468-87fc-52b18b631b29', 1, 'adjective', null, 'wealthy, affluent', 'De bor i et velhavende kvarter.', 'They live in a wealthy neighbourhood.'), ('dokumentar', 'word', 'ab6eeabf-47b4-567a-92af-cadccbe2a95f', 1, 'noun', 'en', 'documentary', 'Vi så en dokumentar om havet i går.', 'We watched a documentary about the ocean yesterday.'), ('kup', 'word', 'f929fe9b-f79f-537d-90da-2862bd5937fc', 1, 'noun', 'et', 'coup, putsch', 'Militæret gennemførte et kup i landet.', 'The military carried out a coup in the country.'), ('kup', 'word', '228ddabf-d450-5ddf-93bf-