oung people.'), ('udråbe', 'word', '615fbf19-a784-5335-b2f6-38b77be18b0b', 1, 'verb', null, 'to declare, to proclaim (someone as something)', 'Han blev udråbt til vinder af konkurrencen.', 'He was declared the winner of the competition.'), ('tilgodese', 'word', '54660d81-6a9a-536a-ac1a-23485e842e15', 1, 'verb', null, 'to take into account, to cater to', 'Planen skal tilgodese alle beboernes ønsker.', 'The plan must cater to all the residents'' wishes.'), ('incitament', 'word', 'a3d5f0d7-20c6-589d-8a1f-d5f480d3f315', 1, 'noun', 'et', 'incentive', 'Skattelettelsen giver et incitament til at spare op.', 'The tax cut gives an incentive to save.'), ('rotte', 'word', '30c8b47b-4ecb-5e2c-a464-1746e4bb8164', 1, 'noun', 'en', 'rat', 'Der løb en rotte hen over gaden.', 'A rat ran across the street.'), ('spillested', 'word', '5fa541ac-944b-5128-a959-b5230934ef25', 1, 'noun', 'et', 'venue (for performances)', 'Bandet spillede på et lille spillested i byen.', 'The band played at a small venue in the town.'), ('grænseoverskridende', 'word', '2a66d2f4-765b-569f-b979-13b5f8dde774', 1, 'adjective', null, 'cross-border', 'Kriminalitet kræver ofte et grænseoverskridende samarbejde.', 'Crime often requires cross-border cooperation.'), ('parlamentarisk', 'word', 'ef5484f6-93a4-5fa5-aa80-2a152591dd4c', 1, 'adjective', null, 'parliamentary', 'Regeringen har ikke parlamentarisk flertal.', 'The government does not have a parliamentary majority.'), ('fejlagtig', 'word', '7b712002-e988-5137-ac3c-736e85af2fdb', 1, 'adjective', null, 'erroneous, mistaken', 'Han gav en fejlagtig oplysning til politiet.', 'He gave the police mistaken information.'), ('ensemble', 'word', 'd3064104-63a9-5c04-b6c4-b3801140e178', 1, 'noun', 'et', 'ensemble (musical group)', 'Ensemblet spillede klassisk musik i parken.', 'The ensemble played classical music in the park.'), ('kongerige', 'word', 'b5b1ddaa-74fa-53f4-ae5b-fc3735b0a078', 1, 'noun', 'et', 'kingdom', 'Danmark er et gammelt kongerige.', 'Denmark is an old kingdom.'), ('rutineret', 'word', 'd8f50996-f101-53b2-8501-1ae73936707b', 1, 'adjective', null, 'experienced, seasoned', 'Han er en rutineret forhandler.', 'He is a seasoned negotiator.'), ('vicepræsident', 'word', '185f688f-f26f-53f2-ad7f-8636be22820f', 1, 'noun', 'en', 'vice president', 'Vicepræsidenten holdt talen i stedet for præsidenten.', 'The vice president gave the speech instead of the president.'), ('kortlægge', 'word', '44d3438d-b2c3-5c9f-849b-73999751ff3c', 1, 'verb', null, 'to map, to chart', 'Forskerne vil kortlægge området nøje.', 'The researchers want to carefully map the area.'), ('parallel', 'word', 'a85463e9-7baf-5df6-a603-1f02a195e692', 1, 'adjective', null, 'parallel', 'De to veje er parallelle med hinanden.', 'The two roads are parallel to each other.'), ('urolig', 'word', 'b8451e26-8b89-5baa-98c0-e7e26b2664b4', 1, 'adjective', null, 'anxious, uneasy', 'Hun var urolig for sin søns helbred.', 'She was anxious about her son''s health.'), ('indledning', 'word', '3bae6922-2ece-58cb-a336-22fd01b62631', 1, 'noun', 'en', 'introduction', 'Bogens indledning fanger læserens interesse.', 'The book''s introduction captures the reader''s interest.'), ('røv', 'word', 'c83a92d6-330a-58a7-bd68-211fd420ba0f', 1, 'noun', 'en', 'backside, bum (informal)', 'Han faldt ned på røven på isen.', 'He fell on his backside on the ice.'), ('eng', 'word', '72cca58a-9baf-5f36-9664-892247556875', 1, 'noun', 'en', 'meadow', 'Køerne græssede på engen.', 'The cows grazed on the meadow.'), ('drivkraft', 'word', 'c8070aa1-d381-5084-a7f4-66cd47d71cb5', 1, 'noun', 'en', 'driving force', 'Nysgerrighed er hans største drivkraft.', 'Curiosity is his greatest driving force.'), ('interesseret', 'word', '44f81647-74ec-5560-9220-3364be56b730', 1, 'adjective', null, 'interested', 'Han er meget interesseret i historie.', 'He is very interested in history.'), ('cykelsti', 'word', '2f784733-5dd3-52bb-a967-eb1413b307c4', 1, 'noun', 'en', 'cycle path', 'Der er en bred cykelsti langs vejen.', 'There is a wide cycle path along the road.'), ('beskatning', 'word', '812ea0de-e48b-5c71-a36f-0b81be5fa17b', 1, 'noun', 'en', 'taxation', 'Regeringen vil ændre beskatningen af biler.', 'The government wants to change the taxation of cars.'), ('opsving', 'word', 'fd7fa39e-c08b-55fd-b43f-bdbce4e9caeb', 1, 'noun', 'et', 'upturn, recovery (in the economy)', 'Landet oplever et økonomisk opsving.', 'The country is experiencing an economic upturn.'), ('hjælper', 'word', '6882aa00-d813-55ab-815c-f30611d8e376', 1, 'noun', 'en', 'helper, assistant', 'Hun arbejder som hjælper på plejehjemmet.', 'She works as an assistant at the care home.'), ('migrant', 'word', '44d6b693-1a35-5bde-9b24-7825d082ac55', 1, 'noun', 'en', 'migrant', 'Mange migranter søger arbejde i byen.', 'Many migrants seek work in the city.'), ('producer', 'word', 'e2653133-2b33-53fb-922a-6d6c77a28d22', 1, 'noun', 'en', 'producer', 'Han arbejder som producer på et filmstudie.', 'He works as a producer at a film studio.'), ('tomme', 'word', '27745d1d-c266-54a5-90a2-2f17cc838478', 1, 'noun', 'en', 'inch', 'Skærmen er femten tomme bred.', 'The screen is fifteen inches wide.'), ('høne', 'word', '75053aed-8b23-51d0-a59c-1d19903eb07d', 1, 'noun', 'en', 'hen', 'Hønen lagde et æg i morges.', 'The hen laid an egg this morning.'), ('pirat', 'word', 'de76efcf-f4a1-5530-8b24-7052febeea9d', 1, 'noun', 'en', 'pirate', 'Filmen handler om en berømt pirat.', 'The film is about a famous pirate.'), ('udlægning', 'word', 'eb0c5f56-c0eb-589f-af10-89041b7a5fbf', 1, 'noun', 'en', 'interpretation, reading', 'Hans udlægning af sagen var overraskende.', 'His interpretation of the case was surprising.'), ('kysse', 'word', '1093ddb8-0d76-56ca-b37d-1503ed440f21', 1, 'verb', null, 'to kiss', 'Han kyssede hende på kinden.', 'He kissed her on the cheek.'), ('anfører', 'word', '8121413b-738f-5098-9927-3707ae02211c', 1, 'noun', 'en', 'captain (of a team), leader', 'Han er anfører for landsholdet.', 'He is the captain of the national team.'), ('vedta